attribute "tsugumi";
namespace quake;
table QuakeFiles { value:string; }
table Outputs { data:QuakeFiles (required, tsugumi: "directory"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.certifi ];
  };
}

